import{_ as a,a as t,o as i,ai as n}from"./chunks/framework.BbOtTPsL.js";const l=JSON.parse('{"title":"Shipments","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/sales/shipments/index.md","filePath":"api/graphql-api/admin/sales/shipments/index.md","lastUpdated":1781099665000}'),r={name:"api/graphql-api/admin/sales/shipments/index.md"};function s(h,e,d,o,p,m){return i(),t("div",null,e[0]||(e[0]=[n('<h1 id="shipments" tabindex="-1">Shipments <a class="header-anchor" href="#shipments" aria-label="Permalink to &quot;Shipments&quot;">​</a></h1><p>The Shipments menu is the store-wide list of every shipment that has been created across all orders. It mirrors the admin <strong>Sales → Shipments</strong> screen.</p><h2 id="when-a-row-appears-here" tabindex="-1">When a row appears here <a class="header-anchor" href="#when-a-row-appears-here" aria-label="Permalink to &quot;When a row appears here&quot;">​</a></h2><p>A shipment row exists only after a shipment has been <strong>created</strong> for an order (the Create Shipment mutation). Placing or invoicing an order does not by itself create a shipment; until one is created, the order has no row in this menu.</p><h2 id="what-a-shipment-records" tabindex="-1">What a shipment records <a class="header-anchor" href="#what-a-shipment-records" aria-label="Permalink to &quot;What a shipment records&quot;">​</a></h2><p>A shipment records which items, in what quantity, were dispatched — and from which inventory source. It can optionally carry a shipping carrier (<code>carrierCode</code> / <code>carrierTitle</code>) and a tracking number (<code>trackNumber</code>). An order can be shipped in parts: each partial dispatch creates its own shipment, so a single order may have several shipment rows, each covering a subset of its items from a (possibly different) inventory source.</p><h2 id="shipped-to-address" tabindex="-1">Shipped-to address <a class="header-anchor" href="#shipped-to-address" aria-label="Permalink to &quot;Shipped-to address&quot;">​</a></h2><p>The <code>shippingAddress</code> carried on each shipment, and the <code>shippedTo</code> name, come from the <strong>order&#39;s shipping address</strong> — the destination the items were dispatched to. The order&#39;s billing address is also included as <code>billingAddress</code> for context.</p><h2 id="payment-and-shipping" tabindex="-1">Payment and Shipping <a class="header-anchor" href="#payment-and-shipping" aria-label="Permalink to &quot;Payment and Shipping&quot;">​</a></h2><p>The shipment detail also surfaces the order&#39;s Payment and Shipping info — the payment method and its title, the order currency, and the shipping method, its title and price — matching the admin Shipment view&#39;s &quot;Payment and Shipping&quot; panel. The shipping fields can be <code>null</code> when the order had no shipping method (e.g. virtual/free).</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/sales/shipments/list.html">List shipments</a></td><td><code>adminShipments</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/get-shipment.html">Get a single shipment</a></td><td><code>adminShipment(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/sales/orders/create-shipment.html">Create shipment</a></td><td><code>createAdminShipment</code> mutation</td></tr></tbody></table><p>Shipment <strong>creation</strong> runs against an order — see <a href="/api/graphql-api/admin/sales/orders/create-shipment.html">Create Shipment</a>.</p><p>All Shipments operations require the <code>sales.shipments.view</code> permission and an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',14)]))}const u=a(r,[["render",s]]);export{l as __pageData,u as default};
